   708  QByteArray KArchiveFile::data() const
   709  {
   710      bool ok = archive()->device()->seek(d->pos);
   711      if (!ok) {
   712          //qCWarning(KArchiveLog) << "Failed to sync to" << d->pos << "to read" << name();
   713      }
   714
   715      // Read content
   716      QByteArray arr;
   717      if (d->size) {
   718          arr = archive()->device()->read(d->size);
   719          Q_ASSERT(arr.size() == d->size);
   720      }
   721      return arr;
   722  }
