   734  static QFileDevice::Permissions withExecutablePerms(
   735      QFileDevice::Permissions filePerms,
   736      mode_t perms)
   737  {
   738      if (perms & 01)
   739        filePerms |= QFileDevice::ExeOther;
   740
   741      if (perms & 010)
   742        filePerms |= QFileDevice::ExeGroup;
   743
   744      if (perms & 0100)
   745        filePerms |= QFileDevice::ExeOwner;
   746
   747      return filePerms;
   748  }
