   750  bool KArchiveFile::copyTo(const QString &dest) const
   751  {
   752      QFile f(dest + QLatin1Char('/')  + name());
   753      if (f.open(QIODevice::ReadWrite | QIODevice::Truncate)) {
   754          QIODevice *inputDev = createDevice();
   755
   756          // Read and write data in chunks to minimize memory usage
   757          const qint64 chunkSize = 1024 * 1024;
   758          qint64 remainingSize = d->size;
   759          QByteArray array;
   760          array.resize(int(qMin(chunkSize, remainingSize)));
  1080      KArchiveDirectory *parentDir = rootDir();
  1081      QString fileName(name);
  1082      int i = name.lastIndexOf(QLatin1Char('/'));
  1083      if (i != -1) {
  1084          QString dir = name.left(i);
  1085          fileName = name.mid(i + 1);
  1086          //qCDebug(KArchiveLog) << "ensuring" << dir << "exists. fileName=" << fileName;
  1087          parentDir = findOrCreate(dir);
  1088      }
  1089
  1090      // delete entries in the filelist with the same fileName as the one we want
  1091      // to save, so that we don't have duplicate file entries when viewing the zip
  1092      // with konqi...
  1093      // CAUTION: the old file itself is still in the zip and won't be removed !!!
  1094      QMutableListIterator<KZipFileEntry *> it(d->m_fileList);
  1095      //qCDebug(KArchiveLog) << "fileName to write: " << name;
  1096      while (it.hasNext()) {
  1097          it.next();
  1098          //qCDebug(KArchiveLog) << "prepfileName: " << it.current()->path();
  1099          if (name == it.value()->path()) {
  1100              // also remove from the parentDir
  1101              parentDir->removeEntry(it.value());
  1102              //qCDebug(KArchiveLog) << "removing following entry: " << it.current()->path();
  1103              delete it.value();
  1104              it.remove();
  1105          }
  1106
  1107      }
  1108
  1109      // construct a KZipFileEntry and add it to list
  1110      KZipFileEntry *e = new KZipFileEntry(this, fileName, perm, modificationTime, user, group, QString(),
  1111                                           name, device()->pos() + 30 + name.length(), // start
  1112                                           0 /*size unknown yet*/, d->m_compression, 0 /*csize unknown yet*/);
  1113      e->setHeaderStart(device()->pos());
  1114      //qCDebug(KArchiveLog) << "wrote file start: " << e->position() << " name: " << name;
  1115      if (!parentDir->addEntryV2(e)) {
  1116          return false;
  1117      }
  1118
  1119      d->m_currentFile = e;
  1120      d->m_fileList.append(e);
  1121
  1122      int extra_field_len = 0;
  1123      if (d->m_extraField == ModificationTime) {
  1124          extra_field_len = 17;    // value also used in finishWriting()
  1125      }
